"""Payment-reference generation.

Mirrors ``packages/deshiqr/src/core/reference.ts``. References are what let a merchant
match a payment to an order; they are not secrets — they are printed on receipts
and encoded in the QR.
"""

from __future__ import annotations

import re
import secrets

from .errors import DeshiQrError

ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789"

#: Default generated reference length. Real bKash dynamic QRs carry a
#: 25-character bill number (tag 62/01), so that is the shape generated by default.
DEFAULT_REFERENCE_LENGTH = 25

_PREFIX_RE = re.compile(r"[A-Za-z0-9]{0,32}")


def _is_integer(value: object) -> bool:
    return isinstance(value, int) and not isinstance(value, bool)


def new_reference(prefix: str = "", length: int = DEFAULT_REFERENCE_LENGTH) -> str:
    """Generate a reference: a prefix plus cryptographically random alphanumerics.

    ``new_reference(prefix="FT80")`` -> e.g. ``"FT80k2Q9xZ1"`` (default length 25).
    """
    if not _is_integer(length) or length < 1 or length > 32:
        raise DeshiQrError(
            "BAD_REFERENCE",
            "Reference length must be an integer between 1 and 32.",
        )
    if not isinstance(prefix, str) or _PREFIX_RE.fullmatch(prefix) is None:
        raise DeshiQrError(
            "BAD_REFERENCE",
            "A reference prefix may only contain letters and digits.",
        )
    if len(prefix) > length:
        raise DeshiQrError(
            "BAD_REFERENCE",
            'Reference prefix "{}" is longer than the requested length {}.'.format(
                prefix, length
            ),
        )

    remaining = length - len(prefix)
    return prefix + "".join(secrets.choice(ALPHABET) for _ in range(remaining))
